-static mrb_value
-mrb_file__getwd(mrb_state *mrb, mrb_value klass)
+static const char*
+path_getwd(mrb_state *mrb)
 {
   char buf[MAXPATHLEN];

-  mrb->c->ci->mid = 0;
   if (GETCWD(buf, MAXPATHLEN) == NULL) {
