+
+    assert_equal "/hoge", File.expand_path("/tmp/..//hoge")
+    assert_equal "/hoge", File.expand_path("////tmp/..///////hoge")
+
+    assert_equal "/", File.expand_path("../../../..", "/")

-  assert_equal "/", File.expand_path("../../../..", "/")
-  if File._getwd[1] == ":"
-    drive_letter = File._getwd[0]
-    assert_equal drive_letter + ":/", File.expand_path(([".."] * 100).join("/"))
-  else
     assert_equal "/", File.expand_path(([".."] * 100).join("/"))
